--- a/src/service.ts
+++ b/src/service.ts
@@ -1,8 +1,34 @@
-import type { ZoneRules } from "./zone.ts";
+import { parseZone, ZoneError, type ZoneRules } from "./zone.ts";

 export const ZONES_URL = "https://tzdata.ops.internal/v1/zones";

+const ZONE_NAME_PATTERN = /^[A-Za-z_]+(?:\/[A-Za-z0-9_+-]+)+$/;
+
 /** Load the rules of a zone from the tz service. */
 export async function fetchZone(name: string): Promise<ZoneRules> {
-  throw new Error("not implemented");
+  if (typeof name !== "string" || !ZONE_NAME_PATTERN.test(name)) {
+    throw new RangeError(`invalid zone name: "${name}"`);
+  }
+  let response: Awaited<ReturnType<typeof fetch>>;
+  try {
+    response = await fetch(`${ZONES_URL}/${name}`);
+  } catch (cause) {
+    throw new ZoneError(`tz service unavailable: ${cause}`);
+  }
+  if (!response.ok) {
+    throw new ZoneError(`tz service unavailable: HTTP ${response.status}`);
+  }
+  let text: string;
+  try {
+    text = await response.text();
+  } catch (cause) {
+    throw new ZoneError(`tz service unavailable: ${cause}`);
+  }
+  let body: unknown;
+  try {
+    body = JSON.parse(text);
+  } catch (cause) {
+    throw new ZoneError(`tz service returned invalid JSON: ${cause}`);
+  }
+  return parseZone(body);
 }
